import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

const runId = process.env.ZEALT_RUN_ID?.replace(/-/g, "_");
if (!runId) {
  throw new Error("ZEALT_RUN_ID environment variable is not set");
}

const productsTableName = `products_${runId}`;

export default defineSchema({
  [productsTableName]: defineTable({
    name: v.string(),
    price: v.number(),
  }),
});

import { query } from "convex/server";

const runId = process.env.ZEALT_RUN_ID?.replace(/-/g, "_");
if (!runId) {
  throw new Error("ZEALT_RUN_ID environment variable is not set");
}

const productsTableName = `products_${runId}` as "products";

export const list = query(async (ctx) => {
  return await ctx.db.query(productsTableName).collect();
});

